-- Owner-only catalog verification. No business reads/writes, no role changes.
\set ON_ERROR_STOP on
BEGIN READ ONLY;
DO $$ BEGIN
 IF current_database()<>'childguard_v2' OR host(inet_server_addr()) IS DISTINCT FROM '127.0.0.1' OR inet_server_port() IS DISTINCT FROM 5432 OR current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'V2 owner target refused'; END IF;
 IF (SELECT count(*) FROM public."_prisma_migrations")<>10 THEN RAISE EXCEPTION 'Unexpected ledger count'; END IF;
 IF EXISTS(SELECT 1 FROM (VALUES ('202610190001_phase1','558509edb058d17c39d59eb25b00e8d494986c8f48bbb792e7c29b707af5990f'),('202610190002_constraints','ec07e4d242b912c03712c5f7f67081da1c938d2d7d1658c15c5be7932f90cd07'),('202610210001_ble_proximity','78b9537d308fb1e919f0446d97f3571c53182f181bce6659657a0af0d33ec3f4'),('202610220001_multi_beacon','524aa22cfac44a7434ac900feeac2ae9262230505e96ce10d6cd125cd1d102c7'),('202610230001_personal_activity','6bd9b95f2c5b707ca6a6c83b4c4fbe5b4eeeb0db5c6dfb13278283297bc0c527'),('202610240001_registration_review','ffc15c752473e5e7ac064a3c4429eb29b3b9b87cc30f3ec18de9884f2ea8fed4'),('202610240002_registration_invariants','d7aad501eff8c74c82842a0042bb32bb57d9ff54435cebe020c949990ef517a0'),('202610250001_admin_session_foundation','d282437ba93dc8491c067e9c02a2202d161693a5a9601e0e127c35d45f94d2e7'),('202610250002_prototype_geofence','976129bbd79152a9a8ee059bc61d228a9630ac23c1d3bc814c3a5fe1c9bfedae'),('202610260001_authorized_pickup','7c29f1c5608276bc6aab4b502f725f7b88819d914812247945a8fee63bb18169')) AS expected(name,sha) LEFT JOIN public."_prisma_migrations" m ON m.migration_name=expected.name WHERE m.checksum IS DISTINCT FROM expected.sha OR m.finished_at IS NULL OR m.rolled_back_at IS NOT NULL OR m.applied_steps_count<>1) THEN RAISE EXCEPTION 'Migration checksum/history mismatch'; END IF;
 IF (SELECT array_agg(e.enumlabel::text ORDER BY e.enumsortorder) FROM pg_enum e JOIN pg_type t ON t.oid=e.enumtypid JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typname='AttendanceStatus') IS DISTINCT FROM ARRAY['NOT_CHECKED_IN','CHECKIN_PENDING','PRESENT','CHECKED_OUT']::text[] THEN RAISE EXCEPTION 'Attendance enum mismatch'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typname='AttendanceStatus' AND pg_get_userbyid(t.typowner)='childguard_v2_migrator') THEN RAISE EXCEPTION 'Enum ownership requires review'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_roles r WHERE rolname='childguard_v2_migrator' AND NOT rolcanlogin AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND NOT rolbypassrls AND NOT has_schema_privilege(rolname,'public','CREATE') AND NOT EXISTS(SELECT 1 FROM pg_auth_members m WHERE m.member=r.oid)) THEN RAISE EXCEPTION 'Migrator is not locked'; END IF;
 IF EXISTS(SELECT 1 FROM pg_stat_activity WHERE usename='childguard_v2_migrator' AND pid<>pg_backend_pid()) THEN RAISE EXCEPTION 'Competing migrator connection'; END IF;
 IF has_table_privilege('childguard_v2_app','public."_prisma_migrations"','SELECT,INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'Runtime ledger access refused'; END IF;
 IF to_regclass('public."AuthorizedPickupPerson"') IS NULL OR to_regclass('public."PickupPhoto"') IS NULL OR to_regclass('public."PickupRequest"') IS NULL THEN RAISE EXCEPTION 'Pickup storage missing'; END IF;
END $$;
SELECT 'BEFORE attendance absence catalog verification passed' AS result;
ROLLBACK;
